xinshengCustomCss:
.xt-root {
    --x-bg: #000000; --x-border: #2f3336; --x-blue: #1d9bf0; --x-text: #e7e9ea; --x-sub: #71767b;
    background: var(--x-bg) !important; color: var(--x-text) !important;
    border: 1px solid var(--x-border); border-radius: 16px; box-shadow: 0 10px 30px rgba(0,0,0,0.9);
    overflow-y: auto; overflow-x: hidden; padding: 0 0 20px 0; 
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    display: block !important; height: auto !important; max-height: 550px !important; position: relative;
}
.xt-root::-webkit-scrollbar { display: none; }

/*⁣‍‌‌⁠‍‍⁠​​‌⁠​‌​​⁠⁠⁠‍‍⁠​​⁠⁠⁠​‍‌‌⁠⁠‍‌‌​‍⁠⁠​⁠‌⁠​‍⁠‌⁠‌‌​‍​‌‌‍‌⁠​‌‍‍‌​⁣ 🌟 1. 顶部推特 Logo 与标题栏 */
.xt-root::before {
    content: "𝕏 \A 热门推文"; white-space: pre;
    display: flex; flex-direction: column; align-items: center; justify-content: center;
    position: sticky; top: 0; z-index: 50; background: rgba(0,0,0,0.85); backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--x-border); padding: 10px 0; box-sizing: border-box;
    font-size: 16px; font-weight: bold; color: #fff; line-height: 1.5;
}

/* ===================================================== */
/* 🐦 2. 推特 Feed 流排版 & 真实头像镶嵌魔法 */
/* ===================================================== */

/* 彻底铲除自带竖线和系统名字 */
.xt-header::before, .xt-header::after { display: none !important; }
.xt-name { display: none !important; }

/* 空间折叠魔法：悬浮真实头像，并将其下沉 6px 完美对齐！ */
.xt-header {
    width: 40px; height: 40px; 
    margin: 15px 0 -40px 15px; /* 负边距拉扯下方推文 */
    padding: 0; background: transparent; border: none; position: relative; z-index: 10;
    transform: translateY(6px); /* 视觉下沉，不挤压边框 */
}
.xt-avatar {
    width: 40px; height: 40px; border-radius: 50%; border: 1px solid var(--x-border);
    margin: 0; background: #15202b; display: block !important;
}

/* 发推人名字栏 (留出左侧 65px 给上方的真实头像) */
.xt-text-tw1Name, .xt-text-tw2Name, .xt-text-tw3Name {
    padding: 15px 15px 2px 65px; color: var(--x-text); font-weight: bold; font-size: 15px; 
    margin-top: 0; border-top: 1px solid var(--x-border);
}

/* 推文正文 */
.xt-text-tw1Text, .xt-text-tw2Text, .xt-text-tw3Text {
    padding: 0 15px 5px 65px; color: var(--x-text); font-size: 15px; line-height: 1.5; text-align: justify;
}

/* 推文蓝色标签 */
.xt-text-tw1Tags, .xt-text-tw2Tags, .xt-text-tw3Tags {
    padding: 0 15px 10px 65px; color: var(--x-blue); font-size: 14px; font-weight: 500;
}

/* 🌟 3. 终极伪元素：采用 \2003 绝对全角空格，彻底封杀重叠与换行！ */
.xt-text-tw1Tags::after, .xt-text-tw2Tags::after, .xt-text-tw3Tags::after {
    /* 使用 3 个全角绝对空格拉开距离 */
    content: "128 \2003\2003\2003 45 \2003\2003\2003 3.2K \2003\2003\2003 12万";
    display: block; color: var(--x-sub); font-size: 13px; font-weight: normal;
    margin-top: 12px; padding-bottom: 12px; border-bottom: 1px solid var(--x-border);

    /* 引入四个纯净版的 Twitter SVG 官方图标 */
    background-image: 
        url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%2371767b' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z'/></svg>"),
        url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%2371767b' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><polyline points='17 1 21 5 17 9'/><path d='M3 11V9a4 4 0 0 1 4-4h14'/><polyline points='7 23 3 19 7 15'/><path d='M21 13v2a4 4 0 0 1-4 4H3'/></svg>"),
        url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%2371767b' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z'/></svg>"),
        url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%2371767b' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><rect x='3' y='3' width='18' height='18' rx='2' ry='2'/><line x1='3' y1='9' x2='21' y2='9'/><line x1='9' y1='21' x2='9' y2='9'/></svg>");
    background-repeat: no-repeat; background-size: 16px 16px;

    /* 精确落位在 \2003 空格的缝隙中 */
    background-position: 0px 1px, 62px 1px, 117px 1px, 184px 1px; 
    padding-left: 22px; line-height: 18px; white-space: nowrap; 
}

/* 推文评论区 */
.xt-list { margin: 0 15px 15px 65px; padding: 10px 0 0 15px; border-left: 2px solid var(--x-border); background: transparent; }
.xt-list-item { position: relative; margin-bottom: 12px; border: none; background: transparent; color: #ccc; font-size: 14px; line-height: 1.5; white-space: pre-wrap; box-shadow: none; padding: 0; }
.xt-list-item::first-line { font-size: 13px; font-weight: bold; color: var(--x-sub); line-height: 1.8; }


/* ===================================================== */
/* 🔒 4. 敏感内容警告隔离线 */
/* ===================================================== */
.xt-text-vidWarn {
    margin: 30px 15px 20px; padding: 15px; background: rgba(29, 155, 240, 0.1); border: 1px solid var(--x-blue);
    border-radius: 8px; color: var(--x-blue); font-size: 13px; font-weight: bold; text-align: center; line-height: 1.5;
}


/* ===================================================== */
/* 🎥 5. 专属私密媒体库 (16:9 横版播放器生成术) */
/* ===================================================== */
.xt-text-vid1Dur, .xt-text-vid2Dur, .xt-text-vid3Dur {
    margin: 0 15px 10px; padding: 0; background: #111; border-radius: 12px;
    width: calc(100% - 30px); aspect-ratio: 16/9; position: relative;
    border: 1px solid var(--x-border); display: block !important;
    font-size: 0 !important; color: transparent !important; box-shadow: inset 0 -40px 40px -20px rgba(0,0,0,0.8);
}
/* 推特风蓝色播放按钮 */
.xt-text-vid1Dur::before, .xt-text-vid2Dur::before, .xt-text-vid3Dur::before {
    content: "▶"; font-size: 20px; color: #fff; line-height: 50px; text-align: center;
    width: 50px; height: 50px; background: rgba(29, 155, 240, 0.9); border-radius: 50%;
    padding-left: 4px; box-sizing: border-box; position: absolute; top: 50%; left: 50%; 
    transform: translate(-50%, -50%); border: 2px solid rgba(255,255,255,0.2); cursor: pointer;
}
/* 右下角时长 & HD */
.xt-text-vid1Dur::after, .xt-text-vid2Dur::after, .xt-text-vid3Dur::after {
    content: "HD"; position: absolute; bottom: 8px; right: 8px; 
    background: rgba(0,0,0,0.8); color: #fff; font-size: 12px; padding: 2px 6px; border-radius: 4px; font-weight: bold; font-family: monospace;
}
/* 视频标题 */
.xt-text-vid1Title, .xt-text-vid2Title, .xt-text-vid3Title {
    color: var(--x-text); font-size: 14px; margin: 0 15px 25px 15px; font-weight: 500; line-height: 1.4;
}

