    background-image: url("https://i.postimg.cc/TP145szK/IMG-5161.png") !important;

    /* 🔧【左侧图标大小调整】 */
    /* 现在的 36px 是图标的宽高，改大变大，改小变小 */
    background-size: 30px !important; 

    /* 🔧【左侧图标位置调整】 */
    /* left 6px 表示距离左边6px (改大往右，改小往左) */
    /* center 表示垂直居中 (如果想微调上下，可以改成比如 10px 或 20px) */
    background-position: left 6px center !important; 
    background-repeat: no-repeat !important;
}

/* 🌟 右侧三个图标 (爱心、点赞、分享) */
.xt-text:nth-of-type(4)::after {
    content: '' !important; 
    position: absolute !important;

    /* 🔧【右侧三个图标整体位置调整】 */
    /* left: 185px 表示整体距离输入框左侧的距离 (改大整体往右，改小整体往左) */
    left: 185px !important; 
    /* top: 6px 表示整体上下偏移 (负数往上，正数往下) */
    top: 6px !important;    

    /* 🔧【右侧图标区域总宽度】 */
    /* 如果你觉得三个图标挤在一起了，就把 100px 改大 (比如 120px) */
    width: 110px !important; 
    height: 26px !important; 

    /* 填入三张图片 */
    background-image: 
        url("https://i.postimg.cc/ZqnMvQGC/IMG-5162.png"), /* 第一个 */
        url("https://i.postimg.cc/xd84NZwd/IMG-5164.png"), /* 第二个 */
        url("https://i.postimg.cc/P527xHRv/IMG-5165.png")  /* 第三个 */
        !important;

    /* 🔧【三个图标各自的大小】 */
    /* 分别对应：第一个, 第二个, 第三个。现在的 24px 是宽高 */
    background-size: 26px, 26px, 26px !important; 

    /* 🔧【三个图标各自的排版位置】 */
    /* left: 靠左, center: 居中, right: 靠右 */
    /* 如果你想手动控制间距，可以写具体像素，比如: 0px center, 40px center, 80px center */
    background-position: 
        left center, 
        center center, 
        right center 
        !important;

    background-repeat: no-repeat !important;
    pointer-events: none !important;
}

/* ================= 6. 心声层 (Node 5) ================= */
.xt-text:nth-of-type(5) {
    display: inline !important; 
    position: relative !important;
